-- ============================================================
-- Seed Course Materials from Google Drive - PART 1 of 2
-- ============================================================

DO $outer$
DECLARE
  unilag_id UUID;
  cs_dept_id UUID;
  v_uploader_id UUID;
BEGIN
  -- 1. Resolve UNILAG and Computer Science IDs
  SELECT id INTO unilag_id FROM public.universities WHERE short_name = 'UNILAG';
  IF unilag_id IS NULL THEN
    RAISE NOTICE 'UNILAG university not found. Skipping materials seeding.';
    RETURN;
  END IF;

  SELECT id INTO cs_dept_id FROM public.departments 
  WHERE university_id = unilag_id AND name = 'Computer Science';
  IF cs_dept_id IS NULL THEN
    RAISE NOTICE 'Computer Science department not found. Skipping materials seeding.';
    RETURN;
  END IF;

  -- 2. Find a valid user to assign as the uploader
  SELECT user_id INTO v_uploader_id FROM public.user_roles WHERE role = 'admin' LIMIT 1;
  IF v_uploader_id IS NULL THEN
    SELECT id INTO v_uploader_id FROM public.profiles LIMIT 1;
  END IF;
  IF v_uploader_id IS NULL THEN
    RAISE NOTICE 'No user found in profiles. Please register at least one user before running this seed script.';
    RETURN;
  END IF;

  -- 3. Define Temporary Seeding Helper Function (using distinct dollar-quoting tag)
  CREATE OR REPLACE FUNCTION pg_temp.seed_material_helper(
    p_title TEXT,
    p_desc TEXT,
    p_type TEXT,
    p_url TEXT,
    p_course_code TEXT,
    p_dept_id UUID,
    p_uploader_id UUID
  ) RETURNS VOID AS $inner$
  BEGIN
    INSERT INTO public.materials (title, description, type, file_url, course_id, uploaded_by, status)
    SELECT 
      p_title,
      p_desc,
      p_type::public.material_type,
      p_url,
      c.id,
      p_uploader_id,
      'approved'::public.material_status
    FROM public.courses c
    WHERE c.code = p_course_code 
      AND c.department_id = p_dept_id
      AND NOT EXISTS (
        SELECT 1 FROM public.materials m 
        WHERE m.file_url = p_url
      );
  END;
  $inner$ LANGUAGE plpgsql;

  -- 4. Call Helper to Seed Materials
  PERFORM pg_temp.seed_material_helper('2023 FSC112 TEST COMPLICATION BY EXPLICIT.pdf', 'Past Question (PQ) for FSC 101 (100 Level, Semester 1) uploaded from Nacos Drive.', 'pdf', 'https://drive.google.com/file/d/1S_gxQBa_otg6liPNiP6EW3ojmdjk4rlI/view?usp=drive_web', 'FSC 101', cs_dept_id, v_uploader_id);
